#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_lgType;
layout(color) uniform half4 amzp_lgColor;
uniform float amzp_lgInten;
uniform float amzp_lgAim;
uniform float amzp_lgRange;
uniform float amzp_lgShadow;
uniform float amzp_lgMark;
    uniform float4x4 nmModel;
    uniform float4x4 nmView;
    uniform float4x4 nmProj;
    float GPS;
    float camOK() { return (nmProj[2][3] > 0.5 && abs(nmProj[0][0]) + abs(nmProj[1][1]) > 1e-6) ? 1.0 : 0.0; }
    float2 scr(float3 w) {
        float4 c = nmProj * (nmView * float4(w, 1.0));
        if (c.w <= 1e-3) return float2(-1e6);
        return (c.xy / c.w) * GPS + screen.zw * 0.5;
    }
    float segD(float2 p, float2 a, float2 b) {
        float2 pa = p - a, ba = b - a;
        float h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);
        return length(pa - ba * h);
    }
    float cover(float d, float w) { return 1.0 - smoothstep(w - 0.75, w + 0.75, d); }
    void amzRender() {
        float4 orig = amzTexture(0, amzScreenNorm());
        if (camOK() < 0.5 || amzp_lgMark <= 0.0) { amzOutput = orig; return; }
        GPS = screen.zw.y / max(screen.zw.y, 1.0);
        float2 pix = float2(amzScreenNorm().x, 1.0 - amzScreenNorm().y) * screen.zw;
        float3 O = nmModel[3].xyz;
        float2 c = scr(O);
        float R = 15.0 * GPS * amzp_lgMark;
        float d = length(pix - c);
        float3 lc = amzp_lgColor.rgb;
        float core = cover(d, R * 0.42);
        float a = 0.0;
        if (int(amzp_lgType) == 0) {
            float rays = 0.0;
            for (int k = 0; k < 8; k++) {
                float an = float(k) * 0.785398;
                float2 u = float2(cos(an), sin(an));
                rays = max(rays, cover(segD(pix, c + u * R * 0.62, c + u * R), 1.1 * GPS));
            }
            float3 D = int(amzp_lgAim) == 1 ? nmModel[2].xyz : -O;
            if (dot(D, D) < 1e-6) D = float3(0.0, 1.0, 0.0);
            D = normalize(D);
            float2 e = scr(O + D * 120.0 * amzp_lgMark);
            float ln = (e.x > -1e5) ? cover(segD(pix, c + normalize(e - c + 1e-6) * R * 1.05, e), 1.0 * GPS) : 0.0;
            float tip = (e.x > -1e5) ? cover(length(pix - e), 2.6 * GPS) : 0.0;
            a = max(max(core, rays), max(ln * 0.85, tip));
        } else {
            float glow = exp(-max(d - R * 0.42, 0.0) / (R * 0.6)) * 0.45;
            a = max(core, glow);
        }
        float ol = cover(abs(d - R * 0.42), 0.6 * GPS);
        float4 F = float4(mix(lc, float3(0.06), ol * 0.6) * a, a);
        amzOutput = F + orig * (1.0 - F.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
